from itertools import product
imp=lambda a,b: (not a) or b
# per-ball sentences; G = game(ball,rugby), R = shape(ball,round)
s={1:lambda G,R: imp(not G,R), 2:lambda G,R: imp(not R,G),
   3:lambda G,R: imp(G,not R), 4:lambda G,R: imp(R,not G)}
strong=lambda G,R: R==(not G)          # round exactly when not rugby
weak=lambda G,R: imp(not G,R)          # only: non-rugby balls are round
opts={'A':(1,3),'B':(1,2),'C':(2,3),'D':(3,4)}
# check forall-sentences over every interpretation on domains of 1..3 balls
def forall(dom,f): return all(f(G,R) for G,R in dom)
res={k:{'strong':True,'weak':True} for k in opts}
for n in (1,2,3):
    for dom in product(product([False,True],repeat=2),repeat=n):
        for k,(i,j) in opts.items():
            v=forall(dom,s[i]) and forall(dom,s[j])
            res[k]['strong']&= v==forall(dom,strong)
            res[k]['weak']&= v==forall(dom,weak)
for k in opts: print(k, opts[k], res[k])
print('s1==s2:',all(s[1](G,R)==s[2](G,R) for G,R in product([0,1],repeat=2)),
      's3==s4:',all(s[3](G,R)==s[4](G,R) for G,R in product([0,1],repeat=2)))
# A {'strong': True}, B {'weak': True}, C {'strong': True}, D neither -> strong reading gives A;C
